// Cell is one table cell.
type Cell struct {
	Text, Href, Rel string
	Title           string      // hover text (a full fingerprint, the exact time); escaped like every text
	Status          view.Status // set: the text is a status
	Mono, Num       bool
	NoWrap          bool
	Break           bool // long values (URLs, errors) wrap anywhere
	Posts           []PostCommand
}

type PostField struct{ Name, Value string }

type PostCommand struct {
	Action, CSRF, Label       string
	Disabled, Command, Danger bool
	Fields                    []PostField
}

func postClass(post PostCommand) string {
	if post.Command {
		if post.Danger {
			return "cmd cmd-danger"
		}
		return "cmd"
	}
	if post.Danger {
		return "btn btn-danger"
	}
	return "btn"
}

// Column is one table column.
type Column struct {
	Label string
	Num   bool
}

// Command is a link in the command bar.
type Command struct {
	Label, Href string
	Primary     bool
}

// TableData is a table with commands and filters.
type TableData struct {
	RefreshURL string // optional passive fragment polling
	Adaptive   bool   // wrap every column instead of scrolling narrow tables
	Messages   []view.Message
	Tabs       []view.Tab // a tab row under the messages (TablePage only)
	Title      string     // a heading (in sections)
	Commands   []Command
	Filters    *FormData
	Columns    []Column
	Rows       [][]Cell
	Empty      string
	// More links to the next page (cursor).
	More, MoreLabel string
}

